#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime
import shutil, re, subprocess, tempfile, base64
p=Path(__file__).resolve().parent/'index.html'
if not p.exists(): raise SystemExit('ERROR: Put this script beside index.html.')
t=p.read_text(encoding='utf-8')
for anchor in ['</style>','</body>','</script>','id="stats-filter-card"','const STATS_FILTER_KEY','function getFilteredTransactions','function populateStatsVenueFilter']:
    if anchor not in t: raise SystemExit('ERROR: Missing expected anchor: '+anchor)
if 'Mobile Analytics Filters V2' in t: raise SystemExit('ERROR: V2 is already installed.')
backup=p.with_name('index.html.backup-'+datetime.now().strftime('%Y%m%d-%H%M%S'))
shutil.copy2(p,backup)
d=lambda x: base64.b64decode(x).decode('utf-8')
t=t.replace('</style>',d('')+'\n    </style>',1)
t=t.replace('</body>',d('')+'\n</body>',1)
pos=t.rfind('</script>'); t=t[:pos]+'\n'+d('')+'\n'+t[pos:]
for check in ['Mobile Analytics Filters V2','id="maf-modal"','function mafApply()','position: sticky']:
    if check not in t: shutil.copy2(backup,p); raise SystemExit('ERROR: Validation failed: '+check)
p.write_text(t,encoding='utf-8')
node=shutil.which('node')
if node:
    scripts=re.findall(r'<script(?:\s[^>]*)?>([\s\S]*?)</script>',t,re.I)
    with tempfile.NamedTemporaryFile('w',suffix='.js',delete=False,encoding='utf-8') as f: f.write(scripts[-1]); tmp=f.name
    result=subprocess.run([node,'--check',tmp],capture_output=True,text=True); Path(tmp).unlink(missing_ok=True)
    if result.returncode: shutil.copy2(backup,p); raise SystemExit('ERROR: JavaScript syntax failed; backup restored.\n'+result.stderr)
print('SUCCESS: Mobile Analytics Filters V2 installed.')
print('BACKUP:',backup.name)
